import { randomUUID } from 'node:crypto';
import { createReadStream } from 'node:fs';
import { mkdir, rm, stat, writeFile } from 'node:fs/promises';
import { isAbsolute, join, resolve } from 'node:path';
import type { Readable } from 'node:stream';
import {
  DeleteObjectCommand,
  GetObjectCommand,
  NoSuchKey,
  PutObjectCommand,
  S3Client,
} from '@aws-sdk/client-s3';
import { Injectable, NotFoundException } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import type { EnvironmentVariables } from '../../config/env.validation.js';

/** Storage keys are generated by us: a UUID plus a lowercase extension. Nothing else is valid. */
const KEY_PATTERN = /^[0-9a-f-]{36}\.[a-z0-9]{1,8}$/;

export interface StoredFile {
  stream: Readable;
  size: number;
}

/**
 * Where uploaded material files live (PLAN D15). `STORAGE_DRIVER=local` keeps them on the API
 * server's disk (development, tests); `s3` uses an S3-compatible bucket (Cloudflare R2 in
 * production). Files are always streamed through the API, so downloads keep the module's
 * access rules and the bucket stays private.
 */
export abstract class StorageService {
  async save(data: Buffer, extension: string): Promise<string> {
    const key = `${randomUUID()}.${extension.toLowerCase()}`;
    await this.write(key, data);
    return key;
  }

  async open(key: string): Promise<StoredFile> {
    return this.read(checkKey(key));
  }

  async remove(key: string): Promise<void> {
    return this.delete(checkKey(key));
  }

  protected abstract write(key: string, data: Buffer): Promise<void>;
  protected abstract read(key: string): Promise<StoredFile>;
  protected abstract delete(key: string): Promise<void>;
}

function checkKey(key: string): string {
  if (!KEY_PATTERN.test(key)) throw new NotFoundException('File not found');
  return key;
}

/** Files under UPLOAD_DIR on the API server. */
@Injectable()
export class LocalStorageService extends StorageService {
  private readonly root: string;

  constructor(config: ConfigService<EnvironmentVariables, true>) {
    super();
    const dir = config.get('UPLOAD_DIR', { infer: true });
    this.root = isAbsolute(dir) ? dir : resolve(process.cwd(), dir);
  }

  protected async write(key: string, data: Buffer): Promise<void> {
    await mkdir(this.root, { recursive: true });
    await writeFile(join(this.root, key), data, { flag: 'wx' });
  }

  protected async read(key: string): Promise<StoredFile> {
    const path = join(this.root, key);
    const info = await stat(path).catch(() => null);
    if (!info?.isFile()) throw new NotFoundException('File not found');
    return { stream: createReadStream(path), size: info.size };
  }

  protected async delete(key: string): Promise<void> {
    await rm(join(this.root, key), { force: true });
  }
}

/** Objects in a private S3-compatible bucket (Cloudflare R2: S3_REGION=auto). */
@Injectable()
export class S3StorageService extends StorageService {
  private readonly client: S3Client;
  private readonly bucket: string;
  private readonly prefix: string;

  constructor(config: ConfigService<EnvironmentVariables, true>) {
    super();
    this.bucket = config.get('S3_BUCKET', { infer: true }) ?? '';
    this.prefix = config.get('S3_PREFIX', { infer: true });
    this.client = new S3Client({
      endpoint: config.get('S3_ENDPOINT', { infer: true }),
      region: config.get('S3_REGION', { infer: true }),
      forcePathStyle: config.get('S3_FORCE_PATH_STYLE', { infer: true }),
      credentials: {
        accessKeyId: config.get('S3_ACCESS_KEY_ID', { infer: true }) ?? '',
        secretAccessKey: config.get('S3_SECRET_ACCESS_KEY', { infer: true }) ?? '',
      },
    });
  }

  protected async write(key: string, data: Buffer): Promise<void> {
    await this.client.send(
      new PutObjectCommand({ Bucket: this.bucket, Key: this.prefix + key, Body: data }),
    );
  }

  protected async read(key: string): Promise<StoredFile> {
    try {
      const object = await this.client.send(
        new GetObjectCommand({ Bucket: this.bucket, Key: this.prefix + key }),
      );
      if (!object.Body) throw new NotFoundException('File not found');
      return { stream: object.Body as Readable, size: object.ContentLength ?? 0 };
    } catch (error) {
      if (error instanceof NoSuchKey) throw new NotFoundException('File not found');
      throw error;
    }
  }

  protected async delete(key: string): Promise<void> {
    await this.client.send(
      new DeleteObjectCommand({ Bucket: this.bucket, Key: this.prefix + key }),
    );
  }
}
